def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def inorderSuccessors(tree, queries):
    vals, left, right = _links(tree)
    order = []
    stack = []
    x = 0 if vals else -1
    while stack or x != -1:
        while x != -1:
            stack.append(x)
            x = left[x]
        x = stack.pop()
        order.append(vals[x])
        x = right[x]
    succ = {}
    for i, v in enumerate(order):
        succ[v] = order[i + 1] if i + 1 < len(order) else -1
    return [succ[q] for q in queries]
